typedef enum { NORMAL, PRECAUCION, CRITICA } ALERTA;
typedef struct { float temp; float lluvia; } MEDICION;
typedef struct {
  float sumaTemp;
  float sumaLluvia;
  int cantDias;
  int cantLluviosos;
  float tempMax;
} RESUMEN;

modulos.solucion:
void actualizarResumen(MEDICION medicion, RESUMEN *resumen) {
  resumen->sumaTemp += medicion.temp;
  resumen->sumaLluvia += medicion.lluvia;
  resumen->cantDias++;

  if (medicion.lluvia > 0) {
    resumen->cantLluviosos++;
  }

  if (resumen->cantDias == 1 || medicion.temp > resumen->tempMax) {
    resumen->tempMax = medicion.temp;
  }
}

float temperaturaMedia(RESUMEN resumen) {
  if (resumen.cantDias == 0) {
    return 0.0;
  }

  return resumen.sumaTemp / resumen.cantDias;
}

ALERTA clasificarAlerta(MEDICION medicion) {
  if (medicion.temp >= 40.0 || medicion.lluvia >= 80.0) {
    return CRITICA;
  }

  if (medicion.temp >= 35.0 || medicion.lluvia >= 40.0) {
    return PRECAUCION;
  }

  return NORMAL;
}

