    resumen->tempMax = medicion.temp;
  }
}

float temperaturaMedia(RESUMEN resumen) {
  if (resumen.cantDias == 0) {
    return 0.0;
  }

  return resumen.sumaTemp / resumen.cantDias;
}

ALERTA clasificarAlerta(MEDICION medicion) {
  if (medicion.temp >= 40.0 || medicion.lluvia >= 80.0) {
    return CRITICA;
  }

  if (medicion.temp >= 35.0 || medicion.lluvia >= 40.0) {
    return PRECAUCION;
  }

  return NORMAL;
}

int main() {
  // main de demostración: NO es parte del ejercicio
  RESUMEN resumen;
  MEDICION calurosa;
  MEDICION lluviosa;

  resumen.sumaTemp = 0;
  resumen.sumaLluvia = 0;
  resumen.cantDias = 0;
  resumen.cantLluviosos = 0;
  resumen.tempMax = 0;

  calurosa.temp = 30.5;
  calurosa.lluvia = 0;
  lluviosa.temp = 36.0;
  lluviosa.lluvia = 45.0;

  actualizarResumen(calurosa, &resumen);
  actualizarResumen(lluviosa, &resumen);

  float media = temperaturaMedia(resumen);
  ALERTA primera = clasificarAlerta(calurosa);
  ALERTA segunda = clasificarAlerta(lluviosa);

  printf("%.2f\n", media);

  switch (primera) {
    case NORMAL:
      printf("NORMAL\n");
      break;
    case PRECAUCION:
      printf("PRECAUCION\n");
      break;
    case CRITICA:
      printf("CRITICA\n");
      break;
  }

  switch (segunda) {
    case NORMAL:
      printf("NORMAL\n");
      break;
    case PRECAUCION:
      printf("PRECAUCION\n");
      break;
    case CRITICA:
      printf("CRITICA\n");
      break;
  }

  return 0;
}

